import{_ as a,o as n,c as s,a2 as t}from"./chunks/framework.CT6jiXWi.js";const h=JSON.parse('{"title":"Configuration overrides","description":"","frontmatter":{},"headers":[],"relativePath":"pipeline/guide/concepts/overrides.md","filePath":"pipeline/guide/concepts/overrides.md","lastUpdated":1783589060000}'),d={name:"pipeline/guide/concepts/overrides.md"};function r(o,e,c,i,l,p){return n(),s("div",null,[...e[0]||(e[0]=[t(`<h1 id="configuration-overrides" tabindex="-1">Configuration overrides <a class="header-anchor" href="#configuration-overrides" aria-label="Permalink to &quot;Configuration overrides&quot;">​</a></h1><p>Coded <code>addPipeline({ ... })</code> remains the source of truth for <strong>structure</strong> (source entity/service, target, adapters, query closures, view mapping). Tunable operational knobs can be <strong>overridden at runtime</strong> through the management API and the Pipeline Console. Overrides are persisted in the tracker and re-applied after every process restart — because pipelines always re-register from code on boot, the engine loads the stored JSON delta in <code>_ensureTracker</code> and layers it onto the fresh coded baseline.</p><div class="language- vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>coded addPipeline(config)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>  baseConfig  (normalized, in-memory + tracker.baseConfig)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        │  deep-merge with</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>  overrides   (tracker.overrides JSON)</span></span>
<span class="line"><span>        │</span></span>
<span class="line"><span>        ▼</span></span>
<span class="line"><span>  effective = Pipeline.config  (what runs actually use)</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br><span class="line-number">6</span><br><span class="line-number">7</span><br><span class="line-number">8</span><br><span class="line-number">9</span><br><span class="line-number">10</span><br><span class="line-number">11</span><br></div></div><h2 id="overridable-fields" tabindex="-1">Overridable fields <a class="header-anchor" href="#overridable-fields" aria-label="Permalink to &quot;Overridable fields&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Path</th><th>Effect</th></tr></thead><tbody><tr><td><code>enabled</code></td><td>Pause scheduled ticks (<code>false</code>); manual <code>start</code> / <code>execute</code> still run</td></tr><tr><td><code>mode</code></td><td>Default run mode (<code>delta</code> / <code>full</code> / <code>partial-refresh</code>)</td></tr><tr><td><code>schedule</code></td><td>Interval (ms / time string), cron, and <code>engine</code> (<code>spawn</code> | <code>queued</code>)</td></tr><tr><td><code>retention.retentionDays</code> / <code>retention.maxRuns</code></td><td>Per-pipeline run-history retention (requires global <code>housekeeping</code> config). See <a href="./housekeeping.html">Run housekeeping</a>.</td></tr><tr><td><code>delta.mode</code> / <code>delta.field</code> / <code>delta.dateField</code> / <code>delta.timeField</code></td><td>Watermark strategy for entity-shape reads</td></tr><tr><td><code>source.batchSize</code> / <code>source.delay</code> / <code>source.maxRetries</code> / <code>source.retryDelay</code></td><td>Paging and retry tuning</td></tr><tr><td><code>flags</code></td><td>Entity-cache truncate flags</td></tr><tr><td><code>description</code></td><td>UI label</td></tr></tbody></table><p>Anything else is rejected (<code>source.entity</code>, <code>target.*</code>, <code>viewMapping</code>, <code>source.query</code>, <code>refresh.slice</code>, custom adapters, …). Structural changes require a code change and redeploy.</p><h2 id="live-schedule-changes" tabindex="-1">Live schedule changes <a class="header-anchor" href="#live-schedule-changes" aria-label="Permalink to &quot;Live schedule changes&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Engine</th><th>Live stop/restart without process restart?</th></tr></thead><tbody><tr><td><code>spawn</code> (interval)</td><td>Always — <code>clearInterval</code> + restart</td></tr><tr><td><code>queued</code> (cron / CAP Event Queues)</td><td>Only when the runtime supports named-task <code>unschedule</code> (CDS 10+). On CDS 9 anonymous queues, change requires restart (or switch to <code>spawn</code>).</td></tr></tbody></table><p><code>configView().meta.scheduleLiveChangeSupported</code> surfaces this per pipeline so the console can warn before a doomed call.</p><h2 id="api-surface" tabindex="-1">API surface <a class="header-anchor" href="#api-surface" aria-label="Permalink to &quot;API surface&quot;">​</a></h2><p>On <code>DataPipelineService</code> (programmatic) and bound on <code>/pipeline/Pipelines(...)</code>:</p><ul><li><code>setOverrides(patch)</code> / <code>clearOverrides(keys?)</code> — merge or clear the JSON delta</li><li><code>setEnabled(boolean)</code> — convenience for the pause toggle</li><li><code>setSchedule({ every, cron, engine })</code> / <code>clearSchedule()</code> — schedule overrides (persisted)</li><li><code>configView()</code> — <code>{ base, overrides, effective, fields[], meta }</code> for the coded-vs-override-vs-effective diff</li></ul><p>See <a href="./../../reference/management-service.html">Management Service</a> for OData payloads and <a href="./../pipeline-console.html">Pipeline Console</a> for the UI.</p>`,13)])])}const b=a(d,[["render",r]]);export{h as __pageData,b as default};
